<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Competition;use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\Support\Facades\Storage;class CompetitionController extends Controller{public function index(){return view('admin.competitions.index',['items'=>Competition::latest('starts_at')->paginate(30)]);}public function create(){return view('admin.competitions.form',['item'=>new Competition]);}public function store(Request $r){Competition::create($this->data($r));return redirect()->route('admin.competitions.index')->with('ok','Событие добавлено');}public function edit(Competition $competition){return view('admin.competitions.form',['item'=>$competition]);}public function update(Request $r,Competition $competition){$oldImage=$competition->image;$oldDocument=$competition->document;$d=$this->data($r,$competition);$competition->update($d);if(isset($d['image'])&&$oldImage&&$oldImage!==$d['image'])Storage::disk('public')->delete($oldImage);if(isset($d['document'])&&$oldDocument&&$oldDocument!==$d['document'])Storage::disk('public')->delete($oldDocument);return redirect()->route('admin.competitions.index')->with('ok','Сохранено');}public function destroy(Competition $competition){if($competition->image)Storage::disk('public')->delete($competition->image);if($competition->document)Storage::disk('public')->delete($competition->document);$competition->delete();return back();}private function data(Request $r,?Competition $item=null){$d=$r->validate(['title'=>'required|max:255','kind'=>'required|in:competition,festival','description'=>'nullable','place'=>'nullable|max:255','starts_at'=>'nullable|date','ends_at'=>'nullable|date','image'=>'nullable|image|max:10240','document'=>'nullable|file|max:20480|mimes:pdf,doc,docx']);$base=Str::slug($r->input('slug')?:$d['title'])?:'competition';$slug=$base;$i=2;while(Competition::where('slug',$slug)->when($item,fn($q)=>$q->where('id','!=',$item->id))->exists())$slug=$base.'-'.$i++;$d['slug']=$slug;if($r->hasFile('image'))$d['image']=$r->file('image')->store('competitions','public');if($r->hasFile('document'))$d['document']=$r->file('document')->store('competitions/documents','public');$d['is_published']=$r->boolean('is_published');return $d;}}